// Generated by Cypress Author on 2026-11-25.
// Définir les prix attendus du catalogue standard Swag Labs.
const expectedPrices = {
    'Sauce Labs Backpack': '$29.99',
    'Sauce Labs Bike Light': '$9.99',
    'Sauce Labs Bolt T-Shirt': '$15.99',
    'Sauce Labs Fleece Jacket': '$49.99',
    'Sauce Labs Onesie': '$7.99',
    'Test.allTheThings() T-Shirt (Red)': '$15.99',
};

// Regrouper le scénario de vérification de l'exactitude des prix.
describe('Swag Labs inventory price accuracy', () => {
    // Se connecter avant le scénario avec la commande partagée.
    beforeEach(() => {
        // Connecter l'utilisateur standard et ouvrir l'inventaire.
        cy.login();
    });

    // Fermer la session après le scénario avec la commande partagée.
    afterEach(() => {
        // Déconnecter l'utilisateur après les vérifications.
        cy.logout();
    });

    // Définir le scénario qui compare chaque produit à son prix attendu.
    it('affiche le prix exact pour chacun des six produits', () => {
        // Vérifier que la page de l'inventaire est affichée.
        cy.get('[data-test="title"]').should('be.visible').and('have.text', 'Products');

        // Vérifier qu'il y a six produits et comparer leurs prix au catalogue attendu.
        cy.get('.inventory_item').should('have.length', 6).each(($product) => {
            // Lire le nom visible du produit pour sélectionner son prix attendu.
            cy.wrap($product).find('.inventory_item_name').invoke('text').then((name) => {
                // Nettoyer les espaces autour du nom du produit.
                const productName = name.trim();

                // Vérifier que le nom du produit affiché correspond exactement au nom attendu.
                expect(expectedPrices, `prix attendu pour ${productName}`).to.have.property(productName);
                // Vérifier que le prix affiché correspond exactement au prix attendu.
                cy.wrap($product).find('.inventory_item_price').should('be.visible').and('have.text', expectedPrices[productName]);
            });
        });
    });
});
